<script setup lang="ts">
// 标签管理页：/manage/tag（管理 tab 侧边栏）。
//
// 2026-10-11 精简后的定位：只管两件事——
//   1. 通用名：一个概念 = 一组同级叫法，从叫法里选一个作为展示名（也可以输入全新叫法，
//      旧名直接废弃、不降为别名）；
//   2. 置顶排序：控制标签在标签云里的固定顺序。
// 合并、别名增删、挂载题目、变更历史、疑似重复巡检、「人工设定 / AI 管理」两态等
// 机制已全部移除——那些是标签模型收敛前（生命周期/锁定）时代的产物。
import { computed, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetEnrichTagManageList,
  PostEnrichTagPin,
  PostEnrichTagRename,
} from "@/apis/problem-enrichment";
import type { EnrichTagManageItem } from "@/types/problem-enrichment";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// 展示名长度上限：与后端 tagNameMaxRunes / tag.name varchar(20) 对齐
const TAG_NAME_MAX = 20;

// 每页条数：默认随断点（移动端一屏能扫的行更少），也允许用户自己改
const pageSize = ref(isMobile.value ? 20 : 50);

// ── 筛选与列表 ──
const loading = ref(false);
const list = ref<EnrichTagManageItem[]>([]);
const total = ref(0);
const page = ref(1);
const keyword = ref("");
// 已提交的检索词：只有回车/点搜索才更新，避免每敲一个字都打一次后端
const submittedKeyword = ref("");

const columns = [
  { colKey: "name", title: "通用名", minWidth: 160 },
  { colKey: "aliases", title: "别名（其余叫法）", minWidth: 220 },
  { colKey: "problem_count", title: "挂题数", width: 90 },
  { colKey: "source", title: "来源", width: 90 },
  { colKey: "operation", title: "操作", width: 300, fixed: "right" as const },
];

const fetchList = async () => {
  loading.value = true;
  try {
    const res = await GetEnrichTagManageList(
      submittedKeyword.value,
      page.value,
      pageSize.value
    );
    if (res.code === 0) {
      list.value = res.data?.list ?? [];
      total.value = res.data?.total ?? 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载标签列表失败");
  } finally {
    loading.value = false;
  }
};

// 回车或点「搜索」才提交关键词
const onKeywordSubmit = () => {
  submittedKeyword.value = keyword.value.trim();
  page.value = 1;
  fetchList();
};

const onPageChange = () => {
  fetchList();
};

const onPageSizeChange = () => {
  page.value = 1;
  fetchList();
};

// 断点切换会改变每页条数：回到第一页重取，避免页码指到不存在的页
watch(isMobile, (mobile) => {
  pageSize.value = mobile ? 20 : 50;
  page.value = 1;
  fetchList();
});

// ── 选择通用名：从「当前通用名 + 全部别名」里点选 ──
const pickVisible = ref(false);
const pickTag = ref<EnrichTagManageItem | null>(null);
const pickSubmitting = ref(false);

const openPickDialog = (tag: EnrichTagManageItem) => {
  pickTag.value = tag;
  pickVisible.value = true;
};

const handlePickAlias = async (alias: string) => {
  const tag = pickTag.value;
  if (!tag || pickSubmitting.value) {
    return;
  }
  pickSubmitting.value = true;
  try {
    const res = await PostEnrichTagRename(tag.id, alias);
    if (res.code === 0) {
      ShowTextTipsSuccess(globalProperties, `通用名已改为「${alias}」，旧名「${tag.name}」已废弃`);
      pickVisible.value = false;
      await fetchList();
    } else {
      // 100126 重名 / 100127 名字非法：后端给的就是可读的业务提示
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "切换通用名失败");
  } finally {
    pickSubmitting.value = false;
  }
};

// ── 改名：输入一个全新叫法（旧名直接废弃、不降为别名） ──
const renameVisible = ref(false);
const renameTag = ref<EnrichTagManageItem | null>(null);
const renameName = ref("");
const renameSubmitting = ref(false);

const renameLength = computed(() => Array.from(renameName.value.trim()).length);
const renameValid = computed(() => renameLength.value > 0 && renameLength.value <= TAG_NAME_MAX);

const openRenameDialog = (tag: EnrichTagManageItem) => {
  renameTag.value = tag;
  renameName.value = "";
  renameVisible.value = true;
};

const handleRenameSubmit = async () => {
  if (!renameTag.value || !renameValid.value) {
    return;
  }
  renameSubmitting.value = true;
  try {
    const res = await PostEnrichTagRename(renameTag.value.id, renameName.value.trim());
    if (res.code === 0) {
      ShowTextTipsSuccess(globalProperties, "通用名已更新");
      renameVisible.value = false;
      await fetchList();
    } else {
      // 100126 重名 / 100127 名字非法：后端给的就是可读的业务提示
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "改名失败");
  } finally {
    renameSubmitting.value = false;
  }
};

// ── 置顶 / 排序：只影响标签云的展示顺序，不改变标签语义 ──
// 新置顶追加到置顶区末尾（取现有最大 order + 1），取消时归零——后端也会归零，
// 这里同步是为了列表立刻反映，不用等刷新。
const togglePin = async (row: EnrichTagManageItem) => {
  const nextPinned = !row.pinned;
  const maxOrder = list.value
    .filter((t) => t.pinned)
    .reduce((max, t) => Math.max(max, t.pin_order ?? 0), 0);
  const nextOrder = nextPinned ? maxOrder + 1 : 0;
  try {
    const res = await PostEnrichTagPin(row.id, nextPinned, nextOrder);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    row.pinned = nextPinned;
    row.pin_order = nextOrder;
    ShowTextTipsSuccess(
      globalProperties,
      nextPinned ? "已置顶：它会固定出现在标签云最前" : "已取消置顶"
    );
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// 置顶区内上移 / 下移：与相邻的置顶标签**交换** pin_order。
//
// 用两次 SetTagPinned 而不是新开一个 swap 接口——置顶是低频操作，
// 省一个接口、少一处后端逻辑值得。两次调用之间若失败，两个标签会拿到相同的
// pin_order，此时排序由 update_time 兜底，不会出现「标签消失」这类硬故障。
const movePin = async (row: EnrichTagManageItem, delta: number) => {
  const pinnedList = list.value
    .filter((t) => t.pinned)
    .sort((a, b) => (a.pin_order ?? 0) - (b.pin_order ?? 0));
  const idx = pinnedList.findIndex((t) => t.id === row.id);
  const target = idx >= 0 ? pinnedList[idx + delta] : undefined;
  if (!target) {
    return;
  }
  const myOrder = row.pin_order ?? 0;
  const targetOrder = target.pin_order ?? 0;
  try {
    const first = await PostEnrichTagPin(row.id, true, targetOrder);
    if (first.code !== 0) {
      ShowErrorTips(globalProperties, first.code);
      return;
    }
    const second = await PostEnrichTagPin(target.id, true, myOrder);
    if (second.code !== 0) {
      ShowErrorTips(globalProperties, second.code);
      return;
    }
    row.pin_order = targetOrder;
    target.pin_order = myOrder;
    ShowTextTipsSuccess(globalProperties, delta < 0 ? "已上移" : "已下移");
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// ── 展示辅助 ──
// 别名超过 3 个时只铺前 3 个 + 「+N」，全部叫法放进 hover 提示
const aliasTooltip = (row: EnrichTagManageItem) => (row.aliases ?? []).map((a) => a.alias).join("、");

onMounted(() => {
  fetchList();
});
</script>

<template>
  <div class="manage-tag">
    <!-- 筛选区 -->
    <div class="mt-toolbar">
      <t-input
        v-model="keyword"
        class="mt-keyword"
        placeholder="按通用名或别名搜索，回车检索"
        clearable
        @enter="onKeywordSubmit"
        @clear="onKeywordSubmit"
      />
      <t-button theme="primary" variant="outline" @click="onKeywordSubmit">搜索</t-button>
      <t-button variant="outline" @click="fetchList">刷新</t-button>
    </div>

    <!-- 桌面端：一个概念一行 -->
    <div v-if="!isMobile" class="mt-table-wrap">
      <t-table :data="list" :columns="columns" :loading="loading" row-key="id" table-layout="auto">
        <template #name="{ row }">
          <span class="mt-name">{{ row.name }}</span>
        </template>
        <template #aliases="{ row }">
          <span v-if="(row.aliases ?? []).length === 0" class="mt-muted">—</span>
          <template v-else>
            <t-tag
              v-for="a in (row.aliases ?? []).slice(0, 3)"
              :key="a.id"
              size="small"
              variant="light-outline"
              class="mt-alias"
            >
              {{ a.alias }}
            </t-tag>
            <t-tooltip v-if="(row.aliases ?? []).length > 3" :content="aliasTooltip(row)">
              <t-tag size="small" theme="default" variant="light" class="mt-alias">
                +{{ (row.aliases ?? []).length - 3 }}
              </t-tag>
            </t-tooltip>
          </template>
        </template>
        <template #problem_count="{ row }">{{ row.problem_count }}</template>
        <template #source="{ row }">
          <t-tag size="small" :theme="row.source === 'ai' ? 'primary' : 'success'" variant="outline">
            {{ row.source === "ai" ? "AI" : "人工" }}
          </t-tag>
        </template>
        <template #operation="{ row }">
          <t-space size="small" break-line>
            <t-button
              size="small"
              variant="text"
              theme="primary"
              :disabled="(row.aliases ?? []).length === 0"
              @click="openPickDialog(row)"
            >
              选择通用名
            </t-button>
            <t-button
              size="small"
              variant="text"
              :theme="row.pinned ? 'warning' : 'default'"
              @click="togglePin(row)"
            >
              {{ row.pinned ? "取消置顶" : "置顶" }}
            </t-button>
            <template v-if="row.pinned">
              <t-button size="small" variant="text" @click="movePin(row, -1)">上移</t-button>
              <t-button size="small" variant="text" @click="movePin(row, 1)">下移</t-button>
            </template>
            <t-button size="small" variant="text" @click="openRenameDialog(row)">改名</t-button>
          </t-space>
        </template>
      </t-table>
    </div>

    <!-- 移动端：同一份数据换成卡片（tdesign 没有 Cell/SwipeCell，用原生 div） -->
    <div v-else class="mt-cards">
      <div v-if="list.length === 0 && !loading" class="mt-empty">没有符合条件的标签</div>
      <div v-for="row in list" :key="row.id" class="mt-card">
        <div class="mt-card-head">
          <span class="mt-name mt-name-plain">{{ row.name }}</span>
          <span class="mt-muted">挂题 {{ row.problem_count }}</span>
        </div>
        <div class="mt-card-aliases">
          <span class="mt-muted">别名：</span>
          <template v-if="(row.aliases ?? []).length > 0">
            <t-tag
              v-for="a in (row.aliases ?? []).slice(0, 3)"
              :key="a.id"
              size="small"
              variant="light-outline"
              class="mt-alias"
            >
              {{ a.alias }}
            </t-tag>
            <t-tag
              v-if="(row.aliases ?? []).length > 3"
              size="small"
              theme="default"
              variant="light"
              class="mt-alias"
              @click="openPickDialog(row)"
            >
              +{{ (row.aliases ?? []).length - 3 }}
            </t-tag>
          </template>
          <span v-else class="mt-muted">无</span>
        </div>
        <div class="mt-card-actions">
          <t-button
            size="small"
            variant="text"
            theme="primary"
            :disabled="(row.aliases ?? []).length === 0"
            @click="openPickDialog(row)"
          >
            选择通用名
          </t-button>
          <t-button
            size="small"
            variant="text"
            :theme="row.pinned ? 'warning' : 'default'"
            @click="togglePin(row)"
          >
            {{ row.pinned ? "取消置顶" : "置顶" }}
          </t-button>
          <template v-if="row.pinned">
            <t-button size="small" variant="text" @click="movePin(row, -1)">上移</t-button>
            <t-button size="small" variant="text" @click="movePin(row, 1)">下移</t-button>
          </template>
          <t-button size="small" variant="text" @click="openRenameDialog(row)">改名</t-button>
        </div>
      </div>
    </div>

    <div class="mt-pagination">
      <t-pagination
        v-model="page"
        v-model:page-size="pageSize"
        :total="total"
        :page-size-options="[20, 50, 100]"
        show-jumper
        @current-change="onPageChange"
        @page-size-change="onPageSizeChange"
      />
    </div>

    <!-- 选择通用名：当前通用名与全部别名并列，点别名即切换 -->
    <t-dialog
      v-model:visible="pickVisible"
      :header="pickTag ? `选择通用名：${pickTag.name}` : '选择通用名'"
      width="520px"
      :confirm-btn="null"
      :cancel-btn="'关闭'"
    >
      <p class="mt-dialog-text">
        一个概念只有一行，通用名只是「当前被选中的叫法」。点击某个别名即可把它设为通用名，
        旧通用名会被直接替换（不保留为别名）。
      </p>
      <t-loading :loading="pickSubmitting">
        <div class="mt-pick-list">
          <div class="mt-pick-row">
            <span class="mt-pick-name">{{ pickTag?.name }}</span>
            <t-tag size="small" theme="primary" variant="light">当前通用名</t-tag>
          </div>
          <div v-for="a in pickTag?.aliases ?? []" :key="a.id" class="mt-pick-row">
            <span class="mt-pick-name">{{ a.alias }}</span>
            <t-popconfirm
              :content="`将通用名改为「${a.alias}」？旧名「${pickTag?.name}」会被直接替换`"
              @confirm="handlePickAlias(a.alias)"
            >
              <t-button size="small" variant="text" theme="primary">设为通用名</t-button>
            </t-popconfirm>
          </div>
          <div v-if="(pickTag?.aliases ?? []).length === 0" class="mt-muted">
            该概念暂无别名：点「改名」输入一个全新的通用名
          </div>
        </div>
      </t-loading>
    </t-dialog>

    <!-- 改名对话框：输入全新叫法，旧名直接废弃 -->
    <t-dialog
      v-model:visible="renameVisible"
      header="改名"
      width="560px"
      :confirm-on-enter="false"
      :confirm-loading="renameSubmitting"
      :confirm-btn="{ disabled: !renameValid }"
      @confirm="handleRenameSubmit"
    >
      <p class="mt-dialog-text">
        当前通用名：<b>{{ renameTag?.name }}</b>
      </p>
      <p class="mt-dialog-text">
        改名会把旧名直接替换为新名，旧名不保留为别名。若新名与某个别名相同，即等价于「从别名中选择通用名」。
      </p>
      <t-input
        v-model="renameName"
        :maxlength="TAG_NAME_MAX"
        placeholder="新的通用名（20 字以内）"
        @enter="handleRenameSubmit"
      />
      <div v-if="renameLength > 0 && !renameValid" class="mt-error">
        通用名最长 {{ TAG_NAME_MAX }} 个字
      </div>
    </t-dialog>
  </div>
</template>

